'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),root=path.join(__dirname,'../..'),qrcode=require(root+'/vendor/paper/qrcode.js'),jsQR=require(root+'/vendor/paper/jsQR.js'),PaperScan=require(root+'/paper-scan.js');
const s=fs.readFileSync(root+'/paper-workspace.js','utf8'),homography=new Function(s.slice(s.indexOf('function homography('),s.indexOf('\nfunction darkness'))+'\nreturn homography;')();
const code='UP2:0123456789abcdef0123456789abcdef',qr=qrcode(0,'M');qr.addData(code);qr.make();const n=qr.getModuleCount(),step=104/(n+8);
function sample(turn,shade,offsetX,offsetY,missing=false){const W=1040,H=1280,data=new Uint8ClampedArray(W*H*4);data.fill(shade);for(let k=3;k<data.length;k+=4)data[k]=255;
function put(x,y){x+=offsetX;y+=offsetY;const p=(y*W+x)*4;data[p]=data[p+1]=data[p+2]=Math.round(shade*.22);}
function rect(x,y,w,h){for(let yy=Math.round(y);yy<Math.round(y+h);yy++)for(let xx=Math.round(x);xx<Math.round(x+w);xx++)put(xx,yy);}
for(const [i,[x,y]] of [[28,28],[692,28],[692,972],[28,972]].entries()){if(!missing||i!==3)rect(x-10,y-10,20,20);}
for(let y=0;y<n;y++)for(let x=0;x<n;x++)if(qr.isDark(y,x))rect(568+(x+4)*step,43+(y+4)*step,step,step);
let frame={width:W,height:H,data};for(let t=0;t<turn;t++){const w=frame.width,h=frame.height,d=new Uint8ClampedArray(w*h*4);for(let y=0;y<h;y++)for(let x=0;x<w;x++){const a=(y*w+x)*4,b=(x*h+h-1-y)*4;d.set(frame.data.subarray(a,a+4),b);}frame={width:h,height:w,data:d};}return frame;}
for(const [turn,shade,x,y] of [[0,255,10,10],[1,210,120,100],[2,160,200,140],[3,230,40,200]]){const frame=sample(turn,shade,x,y),decoded=jsQR(frame.data,frame.width,frame.height,{inversionAttempts:'attemptBoth'});assert.equal(decoded?.data,code);const u=PaperScan.analyze(frame,decoded,homography);assert(u.points,'Corners on rotation '+turn);for(let i=0;i<4;i++){const expected=[[28,28],[692,28],[692,972],[28,972]][i];assert(Math.hypot(u.points[i][0]-expected[0]-x,u.points[i][1]-expected[1]-y)<4,'Corner location');}}
const partial=sample(0,255,20,30,true),decoded=jsQR(partial.data,partial.width,partial.height,{inversionAttempts:'attemptBoth'});assert.equal(decoded?.data,code);assert.equal(PaperScan.analyze(partial,decoded,homography).points,null);assert(s.includes('now-qrSeen.since>=2200'));assert(s.includes('render(d,epoch,true)'));assert(s.includes('scanTarget?scanTarget'));console.log('PAPER camera: rotated, dim, off-center and missing-marker frames OK');

(async()=>{const source=s.slice(s.indexOf('async function liveLoop('),s.indexOf("$('cameraStart').addEventListener"));let clock=0,finished=null,stages=[],pending=null;const fn=new Function('videoFrame','qrResult','qrCode','PaperScan','homography','finishCapture','stage','setTimeout','Date','report','stopCamera','initial', 'let cameraEpoch=1,stream=true,scanBusy=false,qrSeen=null,manualCapture=null,cameraTimer=null;'+source+';return liveLoop;')(()=>partial,()=>decoded,()=>code,{analyze:()=>({frame:partial,qr:decoded,points:null})},homography,async(frame,result,points)=>{finished={frame,result,points};},msg=>stages.push(msg),cb=>{pending=cb;return 1;},{now:()=>clock},()=>{},()=>{},null);await fn(1);assert.equal(finished,null);assert(pending);clock=2400;await pending();assert(finished,'QR must open without corner marks after timeout');assert.equal(finished.points,null);assert(stages.some(x=>x.includes('QR найден')));console.log('PAPER live scanner fallback executes after timeout');})().catch(e=>{console.error(e);process.exitCode=1;});
